  1	/**
  2	 * El contrato de la base de errores, el mismo para cada motor.
  3	 *
  4	 * Cada motor (`errorStore.sqlite.test.ts`, `errorStore.postgres.test.ts`) corre
  5	 * esta suite contra una base vacía propia. Lo que cubre es lo que difiere entre
  6	 * motores y se nivela en `dialect.ts`: el id (número en SQLite, `BIGINT` como
  7	 * texto en PostgreSQL), el momento (texto frente a `TIMESTAMPTZ`) y el contexto
  8	 * JSON (texto frente a `JSONB`, que guardaría doblemente codificada una cadena).
  9	 */
 10	import { describe, expect, test } from 'bun:test'
 11	
 12	import type { ErrorStore } from '../src/errorStore/errorStore.ts'
